 if actual not in ($old_world_travel$declare uid uuid := (select auth.uid()); c public.characters; w public.world_players; p public.world_portals; here text; distance double precision; begin if uid is null then raise exception 'NOT_AUTHENTICATED'; end if; perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(uid::text, 1)); c := public.game_lock_character(p_character_id); select * into w from public.world_players where user_id = uid for update; if w.session_id is distinct from p_session_id or w.character_id is distinct from c.id then raise exception 'WORLD_SESSION_REPLACED'; end if; if w.seen_at < now() - interval '15 seconds' then raise exception 'WORLD_SESSION_REPLACED'; end if; if public.game_health(c.data) = 0 or w.dead then raise exception 'CHARACTER_DEAD'; end if; if public.game_wilderness_in_combat(c.id) then raise exception 'IN_COMBAT';end if; if c.data -> 'combatEncounter' ->> 'status' = 'active' and coalesce((c.data->'combatEncounter'->>'engaged')::boolean, (c.data->'combatEncounter'->>'health')::numeric<(c.data->'combatEncounter'->>'maxHealth')::numeric,false) then raise exception 'IN_COMBAT'; end if; here := coalesce(c.data ->> 'location', 'brumaluz'); select * into p from public.world_portals where map = here and id = p_portal; if not found then raise exception 'PORTAL_NOT_FOUND'; end if; -- La casa de Isberto está cerrada hasta que él invita al jugador (los personajes anteriores a la historia, siempre abierta). if p.target_map = 'casa_de_isberto_interior' and not public.game_isberto_house_open(c.data) then raise exception 'PORTAL_LOCKED'; end if; distance := sqrt(power((w.position ->> 'x')::double precision - p.x, 2) + power((w.position ->> 'z')::double precision - p.z, 2)); if distance is null or distance > p.radius + 0.5 then raise exception 'PORTAL_TOO_FAR'; end if; if not public.game_location_contains(p.target_map, (p.target ->> 'x')::double precision, (p.target ->> 'z')::double precision) then raise exception 'INVALID_WORLD_STATE'; end if; c.data := public.game_store(c.id, c.data || jsonb_build_object( 'location', p.target_map, 'position', p.target, 'position_at', extract(epoch from now()))); update public.world_players set position = p.target, facing = coalesce((p.target ->> 'yaw')::double precision, 0) + pi(), jump = 0, movement_credit = 3, seen_at = now(), saved_at = now() where user_id = uid; return jsonb_build_object('status', 'ok', 'location', p.target_map, 'position', p.target, 'players', public.game_world_snapshot(uid), 'encounter', c.data -> 'combatEncounter', 'vitals', public.game_public_vitals(c.data), 'food', jsonb_build_object('buff', c.data -> 'foodBuff', 'revision', c.data -> 'foodRevision', 'at', c.data -> 'food_at'), 'clock', public.world_clock(),'wilderness',public.game_wilderness_view(c.id)); end;$old_world_travel$,$new_world_travel$declare uid uuid := (select auth.uid()); c public.characters; w public.world_players; p public.world_portals; here text; distance double precision; begin if uid is null then raise exception 'NOT_AUTHENTICATED'; end if; perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(uid::text, 1)); c := public.game_lock_character(p_character_id); select * into w from public.world_players where user_id = uid for update; if w.session_id is distinct from p_session_id or w.character_id is distinct from c.id then raise exception 'WORLD_SESSION_REPLACED'; end if; if w.seen_at < now() - interval '15 seconds' then raise exception 'WORLD_SESSION_REPLACED'; end if; if public.game_health(c.data) = 0 or w.dead then raise exception 'CHARACTER_DEAD'; end if; if public.game_wilderness_in_combat(c.id) then raise exception 'IN_COMBAT';end if; if c.data -> 'combatEncounter' ->> 'status' = 'active' and coalesce((c.data->'combatEncounter'->>'engaged')::boolean, (c.data->'combatEncounter'->>'health')::numeric<(c.data->'combatEncounter'->>'maxHealth')::numeric,false) then raise exception 'IN_COMBAT'; end if; here := coalesce(c.data ->> 'location', 'brumaluz'); select * into p from public.world_portals where map = here and id = p_portal; if not found then raise exception 'PORTAL_NOT_FOUND'; end if; -- La casa de Isberto está cerrada hasta que él invita al jugador (los personajes anteriores a la historia, siempre abierta). if p.target_map = 'casa_de_isberto_interior' and not public.game_isberto_house_open(c.data) then raise exception 'PORTAL_LOCKED'; end if; if p.target_map='casa_del_olmo' then if not public.game_home_owned(c.data,'olmo') and public.game_home_owner(c.id,c.data||jsonb_build_object('location',p.target_map))=c.id then raise exception 'Esta casa todavía no te pertenece. Consulta Mis viviendas.';end if; end if; distance := sqrt(power((w.position ->> 'x')::double precision - p.x, 2) + power((w.position ->> 'z')::double precision - p.z, 2)); if distance is null or distance > p.radius + 0.5 then raise exception 'PORTAL_TOO_FAR'; end if; if not public.game_location_contains(p.target_map, (p.target ->> 'x')::double precision, (p.target ->> 'z')::double precision) then raise exception 'INVALID_WORLD_STATE'; end if; if nullif(c.data->'rpg'->'homes'->>'visit','') is not null and (here in ('habitacion_posada_lucero_del_alba','casa_del_olmo') or coalesce(c.data->'rpg'->'homes'->>'visitHome','lucero') is distinct from case p.target_map when 'habitacion_posada_lucero_del_alba' then 'lucero' when 'casa_del_olmo' then 'olmo' end) then c.data:=jsonb_set(c.data,'{rpg,homes}',(c.data->'rpg'->'homes')-'visit'-'visitHome'); end if; c.data := public.game_store(c.id, c.data || jsonb_build_object( 'location', p.target_map, 'position', p.target, 'position_at', extract(epoch from now()))); update public.world_players set position = p.target, facing = coalesce((p.target ->> 'yaw')::double precision, 0) + pi(), jump = 0, movement_credit = 3, seen_at = now(), saved_at = now() where user_id = uid; return jsonb_build_object('status', 'ok', 'location', p.target_map, 'position', p.target, 'players', public.game_world_snapshot(uid), 'encounter', c.data -> 'combatEncounter', 'vitals', public.game_public_vitals(c.data), 'food', jsonb_build_object('buff', c.data -> 'foodBuff', 'revision', c.data -> 'foodRevision', 'at', c.data -> 'food_at'), 'clock', public.world_clock(),'wilderness',public.game_wilderness_view(c.id)); end;$new_world_travel$) then raise exception 'Cozy patch: world_travel differs from the reviewed versions. Preserve its changes and review before applying.';end if;
select trim(regexp_replace(prosrc,'[[:space:]]+',' ','g')) into actual from pg_proc where oid='public.game_world_snapshot(uuid)'::regprocedure;
 if actual not in ($old_game_world_snapshot$select coalesce(jsonb_agg(jsonb_build_object( 'id', w.character_id, 'userId', w.user_id, 'username', p.username, 'vitals', public.game_public_vitals(public.game_food_data(c.id,public.game_party_data(c.id,c.data))), 'data', public.game_public_character(c.data) || jsonb_build_object('name', c.name), 'position', w.position, 'facing', w.facing, 'jump', w.jump, 'wave', w.wave, 'dead', public.game_health(c.data) = 0 ) order by w.character_id), '[]'::jsonb) from public.world_players w join public.characters c on c.id = w.character_id join public.profiles p on p.user_id = w.user_id where w.user_id <> p_user_id and w.seen_at > now() - interval '15 seconds' and coalesce(c.data ->> 'location', 'brumaluz') = ( select coalesce(me.data ->> 'location', 'brumaluz') from public.world_players mine join public.characters me on me.id = mine.character_id where mine.user_id = p_user_id )$old_game_world_snapshot$,$new_game_world_snapshot$select coalesce(jsonb_agg(jsonb_build_object('id',w.character_id,'userId',w.user_id,'username',p.username, 'vitals',public.game_public_vitals(public.game_food_data(c.id,public.game_party_data(c.id,c.data))), 'data',public.game_public_character(c.data)||jsonb_build_object('name',c.name),'position',w.position,'facing',w.facing,'jump',w.jump,'wave',w.wave,'dead',public.game_health(c.data)=0) order by w.character_id),'[]') from public.world_players w join public.characters c on c.id=w.character_id join public.profiles p on p.user_id=w.user_id join public.world_players mine on mine.user_id=p_user_id join public.characters me on me.id=mine.character_id where w.user_id<>p_user_id and w.seen_at>now()-interval '15 seconds' and coalesce(c.data->>'location','brumaluz')=coalesce(me.data->>'location','brumaluz') and public.game_home_owner(c.id,c.data) is not distinct from public.game_home_owner(me.id,me.data)$new_game_world_snapshot$) then raise exception 'Cozy patch: game_world_snapshot differs from the reviewed versions. Preserve its changes and review before applying.';end if;
end $guard$;
