('casa_del_olmo',-4,-2,-1.5707963267948963,-1.3,1.3,-0.32499998062849045,0.32499998062849045),
('casa_del_olmo',-4,3,-1.5707963267948963,-1.3,1.3,-0.32499998062849045,0.32499998062849045),
('casa_del_olmo',-4,0.5,-1.5707963267948963,-1.3,1.3,-0.32499998062849045,0.32499998062849045),
('casa_del_olmo',4,2.5,-1.5707963267948963,-1.3,1.3,-0.32499998062849045,0.32499998062849045),
('casa_del_olmo',4,-2.5,-1.5707963267948963,-1.3,1.3,-0.32499998062849045,0.32499998062849045),
('casa_del_olmo',-2.4,-2.1,0,-0.75,0.75,-1,1),
